//! The generators of the reference pages under `docs/reference/` (`PR-DOC-003`, ADR-0001).
//!
//! Every generated file says that it is generated: a Markdown page opens with an HTML comment and
//! a JSON Schema carries a `$comment`. The output is deterministic (fixed order, LF line endings,
//! one trailing newline), so `scripts/gen_reference.sh --check` and the `reference` test can
//! compare it byte for byte with the committed pages.
//!
//! The outputs are skeletons until the surfaces they document exist: the MCP tools, resources and
//! prompts, the tool-input schemas and the skill sources arrive with v0.2, the canonical JSON form
//! with v0.1 and the style sheet with v0.4. Each of those changes replaces a skeleton below with a
//! call into `tlilli-core` or `tlilli-mcp`, or with the skill build. The command reference is
//! complete already: it renders the clap command tree.

use std::fmt::Write as _;
use std::fs;
use std::path::Path;

/// Why a generator failed: a path that cannot be read or written, or skill sources it cannot
/// document yet. All are user errors (exit code 1, `FR-01-050`); the message names the path.
pub type Failure = String;

/// Where the documentation site serves `docs/`; the JSON Schemas use it for their `$id`.
const SITE: &str = "https://bioedca.github.io/Tlilli/";

/// How to regenerate a page; part of every generated header.
const REGENERATE: &str = "run `scripts/gen_reference.sh` to regenerate it (PR-DOC-003)";

/// The pages `tlilli mcp schema --markdown` writes, in order: file name, title, and what the page
/// lists as a plural noun.
const MCP_PAGES: [(&str, &str, &str); 3] = [
    ("tools.md", "MCP tools", "tools"),
    ("resources.md", "MCP resources", "resources"),
    ("prompts.md", "MCP prompts", "prompts"),
];

/// The Markdown of one MCP reference page. The server offers no tools, resources or prompts
/// before v0.2, so each page says so; v0.2 renders `tlilli-mcp`'s catalog here instead.
fn mcp_page(title: &str, kind: &str) -> String {
    format!(
        "<!-- Generated by `tlilli mcp schema --markdown`. Do not edit this file; {REGENERATE}. -->\n\
         \n# {title}\n\nThis page lists the {kind} that the Tlilli MCP server (`tlilli-mcp`) offers to \
         agents.\n\nThis version of the server offers no {kind}. The first ones arrive with v0.2 \
         ([PRD 11](../../prd/11-fr-v0.2-red-ink.md)).\n"
    )
}

/// Writes `tools.md`, `resources.md` and `prompts.md` into `dir`, creating it if needed.
///
/// # Errors
///
/// A [`Failure`] when `dir` or a page in it cannot be written.
pub fn write_mcp_pages(dir: &Path) -> Result<(), Failure> {
    for (file, title, kind) in MCP_PAGES {
        write_file(&dir.join(file), &mcp_page(title, kind))?;
    }
    Ok(())
}

/// The schemas `tlilli schema dump` writes, in order: file name, title, description, and the
/// release that gives the schema its content. The tool-input schemas join them in v0.2, one file
/// per tool, generated with `schemars` (PRD 21 §3).
const SCHEMAS: [(&str, &str, &str, &str); 2] = [
    (
        "canonical.schema.json",
        "Tlilli canonical JSON",
        "One manuscript in the canonical JSON form that `tlilli export --canonical` writes and \
         `tlilli import --canonical` reads (FR-01-043).",
        "v0.1",
    ),
    (
        "style-sheet.schema.json",
        "Tlilli style sheet",
        "The style sheet of one manuscript (FR-04-001).",
        "v0.4",
    ),
];

/// The text of one skeleton schema: a JSON Schema with no constraints, so it accepts any value
/// until `until` defines the form. Written by hand rather than with `serde_json` so that the key
/// order cannot change with the features another workspace crate turns on.
fn schema_text(file: &str, title: &str, description: &str, until: &str) -> String {
    let fields = [
        (
            "$schema",
            "https://json-schema.org/draft/2020-12/schema".to_owned(),
        ),
        ("$id", format!("{SITE}reference/schemas/{file}")),
        (
            "$comment",
            format!(
                "Generated by `tlilli schema dump`. Do not edit this file; {REGENERATE}. A \
                 skeleton that accepts any value until {until} defines the form."
            ),
        ),
        ("title", title.to_owned()),
        ("description", description.to_owned()),
    ];
    let body: Vec<String> = fields
        .iter()
        .map(|(key, value)| format!("  {}: {}", json_string(key), json_string(value)))
        .collect();
    format!("{{\n{}\n}}\n", body.join(",\n"))
}

/// `value` as a JSON string literal (RFC 8259 §7).
fn json_string(value: &str) -> String {
    let mut literal = String::from('"');
    for character in value.chars() {
        match character {
            '"' => literal.push_str("\\\""),
            '\\' => literal.push_str("\\\\"),
            '\n' => literal.push_str("\\n"),
            '\t' => literal.push_str("\\t"),
            // Writing to a `String` cannot fail.
            control @ '\0'..='\u{1f}' => {
                let _ = write!(literal, "\\u{:04x}", u32::from(control));
            }
            other => literal.push(other),
        }
    }
    literal.push('"');
    literal
}

/// Writes the JSON Schemas into `dir`, creating it if needed.
///
/// # Errors
///
/// A [`Failure`] when `dir` or a schema in it cannot be written.
pub fn write_schemas(dir: &Path) -> Result<(), Failure> {
    for (file, title, description, until) in SCHEMAS {
        write_file(
            &dir.join(file),
            &schema_text(file, title, description, until),
        )?;
    }
    Ok(())
}

/// The command reference: the long help of `command` and of every subcommand, depth first.
/// `term_width(0)` keeps clap's source formatting, so the page depends neither on the terminal
/// nor on whether a workspace crate turns on clap's `wrap_help` feature.
pub fn help_markdown(command: clap::Command) -> String {
    let mut command = command.term_width(0);
    command.build();
    let mut page = format!(
        "<!-- Generated by `tlilli --help-markdown`. Do not edit this file; {REGENERATE}. -->\n\n\
         # Command-line reference\n\nThe help of the `tlilli` command and each of its subcommands. \
         Exit codes: 0 success, 1 user error, 2 internal error (`FR-01-050`).\n"
    );
    push_help(&mut page, &mut command);
    page
}

/// Appends the help section of `command`, then those of its subcommands, to `page`.
fn push_help(page: &mut String, command: &mut clap::Command) {
    let name = command
        .get_bin_name()
        .unwrap_or(command.get_name())
        .to_owned();
    // clap pads the blank line before a `[default: ...]` note; drop trailing spaces per line.
    let help = command.render_long_help().to_string();
    let lines: Vec<&str> = help.trim_end().lines().map(str::trim_end).collect();
    // Writing to a `String` cannot fail.
    let _ = write!(
        page,
        "\n## `{name}`\n\n```text\n{}\n```\n",
        lines.join("\n")
    );
    for subcommand in command.get_subcommands_mut() {
        // clap's generated `help` subcommand repeats what each section already shows.
        if subcommand.get_name() != "help" {
            push_help(page, subcommand);
        }
    }
}

/// Writes the skill reference to `file`. The pack has no skills before v0.2, so the page says so;
/// a `source` that already holds `tlilli-*` skill directories is refused rather than documented
/// wrongly, and nothing is written.
///
/// # Errors
///
/// A [`Failure`] when `source` cannot be read or holds skills, or `file` cannot be written.
pub fn write_skills_page(source: &Path, file: &Path) -> Result<(), Failure> {
    let unreadable = |error: std::io::Error| format!("{}: {error}", source.display());
    let mut skills = Vec::new();
    for entry in fs::read_dir(source).map_err(unreadable)? {
        let entry = entry.map_err(unreadable)?;
        let name = entry.file_name().to_string_lossy().into_owned();
        // `metadata` follows symlinks and, unlike `Path::is_dir`, reports an entry it cannot
        // read instead of counting it as "not a skill".
        if name.starts_with("tlilli-") {
            let path = entry.path();
            let metadata =
                fs::metadata(&path).map_err(|error| format!("{}: {error}", path.display()))?;
            if metadata.is_dir() {
                skills.push(name);
            }
        }
    }
    if !skills.is_empty() {
        skills.sort();
        return Err(format!(
            "{} holds skill sources ({}); their reference arrives with `tlilli skills build` in v0.2",
            source.display(),
            skills.join(", ")
        ));
    }
    let page = format!(
        "<!-- Generated by `tlilli skills build --docs`. Do not edit this file; {REGENERATE}. -->\n\n\
         # Skills\n\nThis page describes the skill pack that teaches agents the Tlilli turn, one \
         section per skill, built from the sources under `skills/`.\n\nThe pack has no skills yet. \
         The first ones, `tlilli-run`, `tlilli-revise` and `tlilli-stub`, arrive with v0.2 \
         ([PRD 11](../prd/11-fr-v0.2-red-ink.md)).\n"
    );
    write_file(file, &page)
}

/// Writes `contents` to `path`, creating the missing parent directories first.
fn write_file(path: &Path, contents: &str) -> Result<(), Failure> {
    let failure = |at: &Path, error: std::io::Error| format!("{}: {error}", at.display());
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|error| failure(parent, error))?;
    }
    fs::write(path, contents).map_err(|error| failure(path, error))
}

#[cfg(test)]
mod tests {
    use super::json_string;

    #[test]
    fn json_strings_escape_quotes_backslashes_and_controls() {
        assert_eq!(json_string("plain `code`"), "\"plain `code`\"");
        assert_eq!(json_string("a \"b\" \\ c"), "\"a \\\"b\\\" \\\\ c\"");
        assert_eq!(json_string("\n\t\r\u{1}"), "\"\\n\\t\\u000d\\u0001\"");
    }
}
